{
  "category_edits": [
    {
      "category": "hyperparameter_tuning",
      "rationale": "Jointly set width to 48, dropout to 0.10 and learning rate to 6e-4 across all four category models. Lower dropout may compensate for reduced capacity, while smaller updates may stabilize fitting. Existing checkpoint metadata and predictor construction propagate width consistently. Preserve six causal blocks, tied embeddings, features, readout, loss, seeds and training limits.",
      "edits": [
        {
          "find": "HIDDEN_UNITS  = int(os.environ.get(\"NEXTITNET_HIDDEN\", \"64\"))",
          "replace": "HIDDEN_UNITS  = int(os.environ.get(\"NEXTITNET_HIDDEN\", \"48\"))"
        },
        {
          "find": "DROPOUT_RATE  = float(os.environ.get(\"NEXTITNET_DROPOUT\", \"0.15\"))",
          "replace": "DROPOUT_RATE  = float(os.environ.get(\"NEXTITNET_DROPOUT\", \"0.10\"))"
        },
        {
          "find": "LR            = float(os.environ.get(\"NEXTITNET_LR\", \"8e-4\"))",
          "replace": "LR            = float(os.environ.get(\"NEXTITNET_LR\", \"6e-4\"))"
        }
      ]
    }
  ],
  "change_summary": "Tune NextItNet width, dropout and learning rate jointly for all four independent category models; existing metadata preserves predictor compatibility."
}
